DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_1','The Twelfth Hour[NEWLINE]Developed-city industry and a synchronized six-turn economy[NEWLINE]Science; production-led Domination[NEWLINE][NEWLINE]Build cities whose normal output is worth multiplying, then plan important work around the Grand Chime. The fixed six-played-turn cadence is an empire schedule; it does not restart when you found a city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_2','Develop workable food and production, establish safe expansion, and note the next Chime. Do not leave a city idle just to make a completion look synchronized; productive normal turns still matter.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_3','Build Clocktowers where their inherited industrial role is useful. Time expensive construction and a healthy science base around the global cadence, and use Pendulum Guards to protect the cities that make the timing valuable.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_4','Turn repeated industrial and research bursts into the normal requirements of your chosen victory. Retain a usable standing army between Chimes, when there is no direct temporary combat-strength reward from the clock itself.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_5','- A Chime benefits every currently owned city.[NEWLINE]- Developed baseline output makes percentage bursts more valuable.[NEWLINE]- Clocktowers and mobile territorial defenders support industrial consolidation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_6','- Five of each six played turns are ordinary turns.[NEWLINE]- The clock does not by itself provide food, expansion safety or a permanent combat bonus.[NEWLINE]- A weak or suppressed city has little healthy output for a burst to multiply.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_7','- Pressure production centres between Chimes and disrupt the jobs supporting their normal output.[NEWLINE]- Do not mistake a production spike for an immediate universal military-strength buff.[NEWLINE]- Force spending on defense before an important scheduled construction push.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_8','- Resetting plans as if founding or reloading restarted the clock.[NEWLINE]- Assuming named game speeds change the six-turn cadence.[NEWLINE]- Delaying necessary infrastructure or defense merely to wait for a Chime.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Luna Network: A mature developed-city economy can contest sustained production through synchronized bursts; it must first survive Luna''s earlier tempo.[NEWLINE][NEWLINE]The Republic of First Drafts: A major Wonder or expensive-construction race can favour a prepared Chime, while Marginalia''s class reward excludes Wonders.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Economic disruption timed before a scheduled burst can reduce the output and construction readiness it was meant to exploit.[NEWLINE][NEWLINE]The Urgal: A positioned attacking force can pressure cities during the long interval between economic bursts.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_CIV_TEXT_10','The schedule uses played turns and the implemented staging model. Native yield settlement and rendering still require the civilization''s documented live acceptance checks.');
