INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_BACKGROUND','Build cities whose normal output is worth multiplying, then plan important work around the Grand Chime. The fixed six-played-turn cadence is an empire schedule; it does not restart when you found a city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_TWELFTH_CIV_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_LEADER_BACKGROUND','Build cities whose normal output is worth multiplying, then plan important work around the Grand Chime. The fixed six-played-turn cadence is an empire schedule; it does not restart when you found a city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_TWELFTH_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_STRATEGY','Build cities whose normal output is worth multiplying, then plan important work around the Grand Chime. The fixed six-played-turn cadence is an empire schedule; it does not restart when you found a city.[NEWLINE][NEWLINE]Develop workable food and production, establish safe expansion, and note the next Chime. Do not leave a city idle just to make a completion look synchronized; productive normal turns still matter.[NEWLINE][NEWLINE]Build Clocktowers where their inherited industrial role is useful. Time expensive construction and a healthy science base around the global cadence, and use Pendulum Guards to protect the cities that make the timing valuable.[NEWLINE][NEWLINE]Turn repeated industrial and research bursts into the normal requirements of your chosen victory. Retain a usable standing army between Chimes, when there is no direct temporary combat-strength reward from the clock itself.');
