INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_LEADER_TEXT_1','The Twelfth Hour[NEWLINE]Developed-city industry and a synchronized six-turn economy[NEWLINE]Science; production-led Domination[NEWLINE][NEWLINE]Build cities whose normal output is worth multiplying, then plan important work around the Grand Chime. The fixed six-played-turn cadence is an empire schedule; it does not restart when you found a city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_LEADER_TEXT_2','Develop workable food and production, establish safe expansion, and note the next Chime. Do not leave a city idle just to make a completion look synchronized; productive normal turns still matter.[NEWLINE][NEWLINE]Build Clocktowers where their inherited industrial role is useful. Time expensive construction and a healthy science base around the global cadence, and use Pendulum Guards to protect the cities that make the timing valuable.[NEWLINE][NEWLINE]Turn repeated industrial and research bursts into the normal requirements of your chosen victory. Retain a usable standing army between Chimes, when there is no direct temporary combat-strength reward from the clock itself.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_THETWELFTHHOUR_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Luna Network: A mature developed-city economy can contest sustained production through synchronized bursts; it must first survive Luna''s earlier tempo.[NEWLINE][NEWLINE]The Republic of First Drafts: A major Wonder or expensive-construction race can favour a prepared Chime, while Marginalia''s class reward excludes Wonders.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Economic disruption timed before a scheduled burst can reduce the output and construction readiness it was meant to exploit.[NEWLINE][NEWLINE]The Urgal: A positioned attacking force can pressure cities during the long interval between economic bursts.');
